use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{fs,fmt::Write,path::{Path,PathBuf},process::Command};
const R:&str="/home/ubuntu/src/zopro-perf-work/g2-native-buckets176";const O:&str="/home/ubuntu/src/zk-tools/zopro/docs/benchmarks/2026-11-06-g2-native-buckets176";
fn hash(b:&[u8])->String{format!("{:x}",Sha256::digest(b))}fn walk(p:&Path)->Vec<PathBuf>{let mut v=vec![];for e in fs::read_dir(p).unwrap(){let p=e.unwrap().path();if p.is_dir(){v.extend(walk(&p))}else{v.push(p)}}v.sort();v}
fn main(){let out=Path::new(O);let original=fs::read(format!("{R}/analysis.json")).unwrap();let decoded=Command::new("gzip").args(["-d","-c"]).arg(out.join("artifacts/receipts-and-helpers.json.gz")).output().unwrap();assert!(decoded.status.success());let archive:Value=serde_json::from_slice(&decoded.stdout).unwrap();let member=&archive[format!("{R}/analysis.json")];assert_eq!(member["sha256"],hash(&original));assert_eq!(member["utf8"].as_str().unwrap().as_bytes(),original);
let mut trimmed:Value=serde_json::from_slice(&original).unwrap();let mut removed=vec![];for k in["caller_receipts","command_receipts"]{assert!(trimmed.as_object_mut().unwrap().remove(k).is_some());removed.push(k);}fs::write(out.join("artifacts/analysis.json"),serde_json::to_vec_pretty(&trimmed).unwrap()).unwrap();fs::copy(format!("{R}/trim-public-analysis.rs"),out.join("artifacts/trim-public-analysis.rs")).unwrap();
let p=out.join("artifacts/publication.json");let mut publication:Value=serde_json::from_slice(&fs::read(&p).unwrap()).unwrap();publication["public_analysis_omits_only_archived_duplicate_fields"]=json!(removed);publication["full_original_analysis_archive_member_sha256"]=json!(hash(&original));publication["public_readme_spacing_reviewed_after_generation"]=json!(true);fs::write(p,serde_json::to_vec_pretty(&publication).unwrap()).unwrap();let mut sums=String::new();let mut count=0;for p in walk(out){if p.file_name().unwrap()=="SHA256SUMS"{continue;}writeln!(sums,"{}  {}",hash(&fs::read(&p).unwrap()),p.strip_prefix(out).unwrap().display()).unwrap();count+=1;}fs::write(out.join("SHA256SUMS"),sums).unwrap();println!("{}",json!({"published_files":count+1,"removed_public_duplicate_fields_only":removed,"full_analysis_losslessly_archived":true}));}
